60	      for (String candidate : CANDIDATE_PATHS) {
61	        VirtualFile vf = dir.findFileByRelativePath(candidate);
62	        if (vf != null && vf.isValid() && !vf.isDirectory()) {
63	          return new Located(vf, dir);
64	        }
65	      }
66	      dir = dir.getParent();
67	    }
68	    return null;
69	  }
70	
71	  private static @Nullable String relativizeAgainst(@NotNull String filePath, @NotNull String rootPath) {
72	    if (filePath.equals(rootPath)) return "";
73	    String prefix = rootPath.endsWith("/") ? rootPath : rootPath + "/";
74	    if (!filePath.startsWith(prefix)) return null;
75	    return filePath.substring(prefix.length());
76	  }
77	
78	  /**
79	   * Returns the owners that apply to {@code file} (last matching rule wins),
80	   * or {@link CodeownersOwnerResolution#NONE} if no rule applies or no
81	   * CODEOWNERS file is reachable from {@code file}'s ancestors.
82	   *
83	   * <p>Must be called under a read action — it accesses VFS and possibly
84	   * document state.
85	   */
86	  public @NotNull CodeownersOwnerResolution resolveOwners(@Nullable VirtualFile file) {
87	    if (file == null || project.isDisposed()) return CodeownersOwnerResolution.NONE;
88	    Located located = locateFor(file);
89	    if (located == null) return CodeownersOwnerResolution.NONE;
90	    String relativePath = relativizeAgainst(file.getPath(), located.root.getPath());
91	    if (relativePath == null) return CodeownersOwnerResolution.NONE;
92	
93	    List<CodeownersRule> rules = getRules(located.codeownersFile);
94	    // Last-match-wins: walk in reverse and stop at the first rule that matches.
95	    for (int i = rules.size() - 1; i >= 0; i--) {
96	      CodeownersRule rule = rules.get(i);
97	      if (rule.matches(relativePath)) {
98	        return new CodeownersOwnerResolution(rule);
99	      }
100	    }
101	    return CodeownersOwnerResolution.NONE;
102	  }
103	
104	  /**
105	   * Resolves the CODEOWNERS context for {@code file}: the governing CODEOWNERS
106	   * file, the file's path relative to that CODEOWNERS file's root, and the
107	   * parsed rules. Returns {@code null} when no CODEOWNERS file is reachable.
108	   *
109	   * <p>Used by owner-suggestion: it needs the repo-relative path (to build a
110	   * new rule and to score path proximity) and the rules, all anchored to the
111	   * same root the resolver uses. Must be called under a read action.
112	   */
113	  public @Nullable FileContext fileContext(@Nullable VirtualFile file) {
114	    if (file == null || project.isDisposed()) return null;
115	    Located located = locateFor(file);
116	    if (located == null) return null;
117	    String relativePath = relativizeAgainst(file.getPath(), located.root.getPath());
118	    if (relativePath == null || relativePath.isEmpty()) return null;
119	    return new FileContext(located.codeownersFile, relativePath, getRules(located.codeownersFile));
120	  }
121	
122	  /**
123	   * @return the CODEOWNERS file that was used for the most recent resolution, or {@code null}.
124	   */
125	  public @Nullable VirtualFile getCodeownersFile() {
126	    Cache c = cache;
127	    return c == null ? null : c.sourceFile;
128	  }
129	
130	  private @NotNull List<CodeownersRule> getRules(@NotNull VirtualFile codeownersFile) {
131	    long stamp = currentStamp(codeownersFile);
132	    Cache existing = cache;
133	    if (existing != null && existing.sourceFile.equals(codeownersFile) && existing.stamp == stamp) {
134	      return existing.rules;
135	    }
136	    CharSequence content = readContent(codeownersFile);
137	    List<CodeownersRule> rules = CodeownersRuleParser.parse(content, codeownersFile);
138	    cache = new Cache(codeownersFile, stamp, rules);
139	    return rules;
140	  }
141	
142	  private @NotNull CharSequence readContent(@NotNull VirtualFile file) {
143	    Document doc = FileDocumentManager.getInstance().getDocument(file);
144	    if (doc != null) return doc.getCharsSequence();
145	    try {
146	      return new String(file.contentsToByteArray(), file.getCharset());
147	    } catch (Exception ignored) {
148	      return "";
149	    }
150	  }
151	
152	  /**
153	   * Uses the document stamp when an editor has the file open (catches
154	   * unsaved edits), and the VFS stamp otherwise.
155	   */
156	  private long currentStamp(@NotNull VirtualFile file) {
157	    Document doc = FileDocumentManager.getInstance().getCachedDocument(file);
158	    return doc != null ? doc.getModificationStamp() : file.getModificationStamp();
159	  }
160	
161	  private record Located(@NotNull VirtualFile codeownersFile, @NotNull VirtualFile root) {
162	  }
163	
164	  /**
165	   * The CODEOWNERS context for a target file: its governing CODEOWNERS file, its
166	   * repo-relative path, and the parsed rules.
167	   */
168	  public record FileContext(@NotNull VirtualFile codeownersFile,
169	                            @NotNull String relativePath,
170	                            @NotNull List<CodeownersRule> rules) {
171	  }
172	
173	  private record Cache(@NotNull VirtualFile sourceFile, long stamp, @NotNull List<CodeownersRule> rules) {
174	  }
175	}
