15	import net.wolfig.codeowls.lexer.CodeownersTokenTypes;
16	import net.wolfig.codeowls.matcher.CodeownersGlob;
17	import org.jetbrains.annotations.NotNull;
18	import org.jetbrains.annotations.Nullable;
19	
20	import javax.swing.*;
21	import java.util.ArrayList;
22	import java.util.Collection;
23	import java.util.List;
24	import java.util.regex.Pattern;
25	
26	/**
27	 * Adds a gutter icon to every wildcard or directory CODEOWNERS rule that lists
28	 * the project files the rule matches; clicking a file in the popup navigates to
29	 * it.
30	 *
31	 * <p>Only glob and directory patterns get a marker — an exact-path rule already
32	 * names its single file. The matched-file list is computed lazily (only when the
33	 * icon is clicked), so the daemon pass that places the marker stays cheap; the
34	 * click reuses {@link CodeownersMatchCounter}'s project walk and
35	 * {@link CodeownersGlob} matching. The list is capped at {@link #MAX_TARGETS}
36	 * to keep the popup responsive on broad rules like {@code /src/**}.
37	 */
38	public final class CodeownersMatchedFilesLineMarkerProvider extends RelatedItemLineMarkerProvider {
39	
40	  static final int MAX_TARGETS = 1000;
41	
42	  private static @NotNull Collection<? extends PsiElement> collectMatchedFiles(@NotNull PsiFile codeownersFile,
43	                                                                               @NotNull String pattern) {
44	    VirtualFile vf = codeownersFile.getVirtualFile();
45	    VirtualFile root = CodeownersMatchCounter.projectRoot(vf);
46	    if (root == null) return List.of();
47	
48	    PsiManager psiManager = PsiManager.getInstance(codeownersFile.getProject());
49	    List<PsiElement> files = new ArrayList<>();
50	    for (String path : matchingPaths(pattern, CodeownersMatchCounter.collectProjectFilePaths(root))) {
51	      VirtualFile child = root.findFileByRelativePath(path);
52	      if (child == null || !child.isValid()) continue;
53	      PsiFile psi = psiManager.findFile(child);
54	      if (psi != null) files.add(psi);
55	    }
56	    return files;
57	  }
58	
59	  /**
60	   * The (up to {@link #MAX_TARGETS}) project paths matched by {@code pattern}.
61	   * Pure, so the selection logic is unit-tested without the IntelliJ platform.
62	   */
63	  static @NotNull List<String> matchingPaths(@NotNull String pattern, @NotNull List<String> projectPaths) {
64	    Pattern compiled = CodeownersGlob.compile(pattern);
65	    List<String> matched = new ArrayList<>();
66	    for (String path : projectPaths) {
67	      if (compiled.matcher(path).matches()) {
68	        matched.add(path);
69	        if (matched.size() >= MAX_TARGETS) break;
70	      }
71	    }
72	    return matched;
73	  }
74	
75	  @Override
76	  protected void collectNavigationMarkers(@NotNull PsiElement element,
77	                                          @NotNull Collection<? super RelatedItemLineMarkerInfo<?>> result) {
78	    ASTNode node = element.getNode();
79	    if (node == null || node.getElementType() != CodeownersTokenTypes.PATTERN) return;
80	
81	    String pattern = element.getText();
82	    if (pattern == null || !CodeownersMatchCounter.isGlobOrDirectoryPattern(pattern)) return;
83	
84	    PsiFile codeownersFile = element.getContainingFile();
85	    if (codeownersFile == null) return;
86	
87	    NotNullLazyValue<Collection<? extends PsiElement>> targets =
88	            NotNullLazyValue.lazy(() -> ReadAction.compute(() -> collectMatchedFiles(codeownersFile, pattern)));
89	
90	    result.add(NavigationGutterIconBuilder.create(AllIcons.Nodes.Folder)
91	            .setTargets(targets)
92	            .setTooltipText("Files matched by this CODEOWNERS rule")
93	            .setPopupTitle("Files Matched by " + pattern)
94	            .setEmptyPopupText("No files match this rule")
95	            .createLineMarkerInfo(element));
96	  }
97	
98	  @Override
99	  public @NotNull String getName() {
100	    return "CODEOWNERS rule matched files";
101	  }
102	
103	  @Override
104	  public @Nullable Icon getIcon() {
105	    return AllIcons.Nodes.Folder;
106	  }
107	}
